# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÖZCÜK TÜRLERİ KARŞILAŞTIRMASI: İSİM, SIFAT VE ZAMİR (T.Y.6.21)</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. İsim (Ad)</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" fill="#1e3a8a">• Varlıkları ve kavramları karşılar:</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11" fill="#1e3a8a">- Özel / Cins: Ankara / şehir</text>\n  <text x="125" y="138" text-anchor="middle" font-size="11" fill="#1e3a8a">- Tekil / Çoğul / Topluluk:</text>\n  <text x="125" y="156" text-anchor="middle" font-size="11" fill="#1e3a8a">asker / askerler / ordu, millet</text>\n  <text x="125" y="176" text-anchor="middle" font-size="11" fill="#1e3a8a">- Somut / Soyut: bayrak / bağımsızlık</text>\n  <text x="125" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Örnek: «Kahraman ordu yürüdü.»</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Sıfat (Ön Ad)</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" fill="#14532d">• İsimlerin önüne gelerek onları</text>\n  <text x="350" y="114" text-anchor="middle" font-size="11" fill="#14532d">niteler veya belirtir:</text>\n  <text x="350" y="136" text-anchor="middle" font-size="11" fill="#14532d">- Niteleme: «al sancak», «cesur er»</text>\n  <text x="350" y="156" text-anchor="middle" font-size="11" fill="#14532d">- İşaret: «bu vatan», «o gün»</text>\n  <text x="350" y="176" text-anchor="middle" font-size="11" fill="#14532d">- Sayı / Belgisiz / Soru: «on kıta»,</text>\n  <text x="350" y="192" text-anchor="middle" font-size="11" fill="#14532d">«bazı şairler», «hangi marş?»</text>\n  <text x="350" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">İsim çekim eki almaz!</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">3. Zamir (Adıl)</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" fill="#581c87">• İsimlerin yerini tutan sözcükler:</text>\n  <text x="575" y="118" text-anchor="middle" font-size="11" fill="#581c87">- Kişi: ben, sen, o, biz, siz, onlar</text>\n  <text x="575" y="138" text-anchor="middle" font-size="11" fill="#581c87">- İşaret: bunu, şunu, oraya</text>\n  <text x="575" y="158" text-anchor="middle" font-size="11" fill="#581c87">- Belgisiz: herkes, kimse, bazıları</text>\n  <text x="575" y="178" text-anchor="middle" font-size="11" fill="#581c87">- Soru: kim, ne, hangisi?</text>\n  <text x="575" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">İsim çekim eki alabilir!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSİM TAMLAMALARI İLE SIFAT TAMLAMASI AYRIMI</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0e7490">1. Belirtili İsim Tamlaması</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" fill="#155e75">• Tamlayan eki (-ın/-in/-un/-ün)</text>\n  <text x="125" y="116" text-anchor="middle" font-size="11" fill="#155e75">+ Tamlanan eki (-ı/-i/-sı/-si)</text>\n  <text x="125" y="142" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0e7490">• «millet-in yıldız-ı»</text>\n  <text x="125" y="164" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0e7490">• «vatan-ın bağr-ı»</text>\n  <text x="125" y="196" text-anchor="middle" font-size="10.5" fill="#334155">Soru: «Neyin / Kimin ...?»</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">2. Belirtisiz İsim Tamlaması</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" fill="#713f12">• Tamlayan ek almaz (yalın),</text>\n  <text x="350" y="116" text-anchor="middle" font-size="11" fill="#713f12">Tamlanan iyelik eki (-ı/-i) alır.</text>\n  <text x="350" y="142" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#854d0e">• «İstiklâl Marş-ı»</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#854d0e">• «bağımsızlık yol-u»</text>\n  <text x="350" y="196" text-anchor="middle" font-size="10.5" fill="#334155">Soru: «Ne ...?» (Ne yolu?)</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">3. Zincirleme &amp; Sıfat Tamlaması</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" fill="#9d174d">• Zincirleme (En az 3 isim):</text>\n  <text x="575" y="116" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">«Türk milletinin bağımsızlık aşkı»</text>\n  <text x="575" y="144" text-anchor="middle" font-size="11" fill="#9d174d">• Sıfat Tamlaması (Sıfat + İsim):</text>\n  <text x="575" y="162" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">«korkusuz asker», «bu şafaklar»</text>\n  <text x="575" y="196" text-anchor="middle" font-size="10.5" fill="#334155">(Tamlanan iyelik eki almaz!)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BAĞIMSIZLIK YOLU TEMASI: METİN TÜRLERİ VE YAZMA SÜRECİ (T.Y.6.1)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Öyküleyici (Anlatmaya Dayalı) Metin</text>\n  <text x="182" y="102" text-anchor="middle" font-size="11" fill="#1e3a8a">• Amaç: Okuru bir olay içinde yaşatmaktır.</text>\n  <text x="182" y="124" text-anchor="middle" font-size="11" fill="#1e3a8a">• Hikâye Unsurları: Olay örgüsü, Şahıs ve</text>\n  <text x="182" y="140" text-anchor="middle" font-size="11" fill="#1e3a8a">varlık kadrosu, Mekân (Yer) ve Zaman.</text>\n  <text x="182" y="164" text-anchor="middle" font-size="11" fill="#1e3a8a">• Plan: Serim (Giriş) ➔ Düğüm (Merak)</text>\n  <text x="182" y="180" text-anchor="middle" font-size="11" fill="#1e3a8a">➔ Çözüm (Sonuç).</text>\n  <text x="182" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Örnek: «Rafadan Tayfa - İstiklâl Marşı», Hikâye, Anı</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Bilgilendirici (Öğretici) Metin</text>\n  <text x="517" y="102" text-anchor="middle" font-size="11" fill="#14532d">• Amaç: Bilgi vermek, açıklamak, ikna etmektir.</text>\n  <text x="517" y="124" text-anchor="middle" font-size="11" fill="#14532d">• Düşünceyi Geliştirme Yolları: Tanımlama,</text>\n  <text x="517" y="140" text-anchor="middle" font-size="11" fill="#14532d">örneklendirme, karşılaştırma, sayısal veriler.</text>\n  <text x="517" y="164" text-anchor="middle" font-size="11" fill="#14532d">• Plan: Giriş (Konu) ➔ Gelişme (Açıklama ve</text>\n  <text x="517" y="180" text-anchor="middle" font-size="11" fill="#14532d">kanıtlar) ➔ Sonuç (Ana düşünce / yargı).</text>\n  <text x="517" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Örnek: Makale, Deneme, Biyografi, Haber Metni</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
